"use strict";

const mongoose = require("mongoose");

// ============================================
// LAX PAIRING SESSION MODEL
// Purpose: Manage laptop pairing lifecycle
// ============================================

const pairingSessionSchema = new mongoose.Schema(
  {
    // Unique identity generated by Local Agent.
    installationId: {
      type: String,
      required: true,
      unique: true,
      trim: true,
    },

    // Hashed one-time pairing code.
    pairingCodeHash: {
      type: String,
      required: true,
      unique: true,
      select: false,
    },

    // Secret used by Local Agent to authenticate polling.
    pollSecretHash: {
      type: String,
      required: true,
      select: false,
    },

    // Laptop metadata.
    deviceName: {
      type: String,
      required: true,
      trim: true,
    },

    os: {
      type: String,
      default: "unknown",
    },

    // Pairing lifecycle.
    status: {
      type: String,
      enum: [
        "pending",
        "processing",
        "approved",
        "delivered",
        "expired",
      ],
      default: "pending",
      index: true,
    },

    // User who approved this pairing.
    userId: {
      type: mongoose.Schema.Types.ObjectId,
      default: null,
    },

    // Assigned permanent laptop ID.
    systemId: {
      type: String,
      default: null,
    },

    // Encrypted device credential.
    encryptedCredential: {
      type: String,
      default: null,
      select: false,
    },

    credentialIv: {
      type: String,
      default: null,
      select: false,
    },

    credentialTag: {
      type: String,
      default: null,
      select: false,
    },

    // Credential delivery expiration.
    expiresAt: {
      type: Date,
      required: true,
      index: true,
    },

    // Retry-safe delivery acknowledgement.
    deliveredAt: {
      type: Date,
      default: null,
    },
  },
  {
    timestamps: true,
  }
);

module.exports = mongoose.model(
  "PairingSession",
  pairingSessionSchema
);